import bpy, math, os
from mathutils import Vector
ROOT='/Users/markwhitley/Documents/Codex Projects/markwhitleydesign'
previous=bpy.context.window.scene
# Replace only scenes generated by this script; retain the user's current scene.
for old in list(bpy.data.scenes):
 if old.name.startswith('Pocket Rally Cockpits V43') and old != previous:
  for obj in list(old.objects):
   mesh=obj.data if obj.type=='MESH' else None
   bpy.data.objects.remove(obj,do_unlink=True)
   if mesh and mesh.users==0:bpy.data.meshes.remove(mesh)
  bpy.data.scenes.remove(old)
scene=bpy.data.scenes.new('Pocket Rally Cockpits V43');bpy.context.window.scene=scene
mats={}
for name,color in [('clay_charcoal',(.035,.05,.045,1)),('clay_trim',(.12,.16,.14,1)),('clay_cream',(.65,.62,.52,1)),('clay_suit',(.055,.065,.08,1)),('clay_blue',(.06,.12,.42,1)),('instrument_face',(.009,.015,.013,1)),('instrument_light',(.68,.78,.49,1)),('limiter',(.18,.025,.01,1))]:
 m=bpy.data.materials.new(name);m.diffuse_color=color;m.use_nodes=True;p=m.node_tree.nodes.get('Principled BSDF');p.inputs['Base Color'].default_value=color;p.inputs['Roughness'].default_value=.83;mats[name]=m
 if name=='instrument_light':p.inputs['Emission Color'].default_value=color;p.inputs['Emission Strength'].default_value=.3

def pos(p):return (p[0],-p[2],p[1])
def empty(name,p,parent=None):
 o=bpy.data.objects.new(name,None);scene.collection.objects.link(o);o.location=pos(p);o.parent=parent;return o

def cube(name,size,p,mat,parent=None,bevel=.02):
 bpy.ops.mesh.primitive_cube_add(size=1,location=pos(p));o=bpy.context.object;o.name=name;o.dimensions=(size[0],size[2],size[1]);bpy.ops.object.transform_apply(location=False,rotation=False,scale=True)
 if bevel:
  b=o.modifiers.new('Soft handmade edge','BEVEL');b.width=bevel;b.segments=2;bpy.ops.object.modifier_apply(modifier=b.name)
 for face in o.data.polygons:face.use_smooth=True
 o.data.materials.append(mats[mat]);o.parent=parent;return o

def beam(name,a,b,width,mat,parent=None):
 a=Vector(pos(a));b=Vector(pos(b));o=cube(name,(width,(b-a).length,width),(0,0,0),mat,parent,width*.2);o.location=(a+b)/2;o.rotation_mode='QUATERNION';o.rotation_quaternion=(b-a).to_track_quat('Z','Y');return o

def disc(name,r,p,mat,parent=None):
 bpy.ops.mesh.primitive_cylinder_add(vertices=24,radius=r,depth=.008,location=pos(p),rotation=(math.pi/2,0,0));o=bpy.context.object;o.name=name;o.data.materials.append(mats[mat]);o.parent=parent;return o

def make(kart):
 kind='kart' if kart else 'rally';root=empty(kind+'_cockpit',(0,0,0));wx=0 if kart else -.18
 cube('dashboard',(.65 if kart else 1.7,.22,.40),(0,-.61,-.8),'clay_charcoal',root,.04)
 cube('instrument_binnacle',(.58,.25,.19),(wx,-.455,-.83),'clay_trim',root,.035)
 cube('bonnet',(1.25,.065,.8),(0,-.65,-1.35),'clay_blue',root,.025)
 cube('footwell',(1.6 if not kart else .65,.08,1.7),(0,-1.1,-.35),'clay_charcoal',root,.025)
 if not kart:
  # Full side panels extend toward the eye; pillars rise from the dash, not floating boxes.
  for x in [-.86,.86]:
   cube('door_panel',(.10,.75,1.8),(x,-.70,-.30),'clay_charcoal',root,.035)
   cube('door_inlay',(.025,.22,.70),(x*.94,-.64,-.1),'clay_trim',root,.02)
   cube('door_handle',(.05,.04,.20),(x*.90,-.50,-.17),'clay_trim',root,.012)
   beam('windscreen_pillar',(x,-.49,-1.03),(x*.85,.65,-.91),.065,'clay_trim',root)
   beam('side_window_frame',(x*.85,.65,-.91),(x,.66,.42),.045,'clay_trim',root)
  cube('roof_lining',(1.64,.055,1.45),(0,.69,-.24),'clay_charcoal',root,.02)
  cube('windscreen_header',(1.5,.08,.1),(0,.65,-.94),'clay_trim',root,.02)
  cube('centre_console',(.22,.40,.55),(.36,-.9,-.5),'clay_trim',root,.04)
  for x in [-.65,.55]:
   for i in range(4):cube('vent',(.12,.012,.018),(x,-.52+i*.022,-.585),'clay_trim',root,.003)
 else:
  for x in [-.39,.39]:beam('kart_frame',(x,-.55,-.9),(x,-.9,.25),.055,'clay_trim',root)
 wheel=empty('steering_wheel',(wx,-.49,-.49),root)
 bpy.ops.mesh.primitive_torus_add(major_radius=.18,minor_radius=.023,major_segments=32,minor_segments=8,rotation=(math.pi/2,0,0));o=bpy.context.object;o.name='wheel_rim';o.parent=wheel;o.data.materials.append(mats['clay_charcoal'])
 for i in range(3):
  a=i*2*math.pi/3;beam('wheel_spoke',(0,0,0),(math.sin(a)*.16,-math.cos(a)*.16,0),.022,'clay_trim',wheel)
 cube('wheel_hub',(.075,.065,.035),(0,0,0),'clay_trim',wheel,.015)
 for side,x in [('left',-.17),('right',.17)]:
  cube('glove_'+side,(.065,.09,.065),(x,.015,.02),'clay_cream',wheel,.022)
  # Unit-long upper/forearm meshes are posed to glove positions in the browser.
  for part in ['fore']:
   cube('arm_'+side+'_'+part,(.075,1,.075),(0,0,0),'clay_suit',root,.028)
 for x,label in [(wx-.14,'speed'),(wx+.14,'rpm')]:
  disc(label+'_face',.104,(x,-.435,-.726),'clay_charcoal',root)
  needle=cube(label+'_needle',(.006,.083,.005),(0,.035,0),'instrument_light',None,.002)
  # Move mesh origin to the dial centre.
  for v in needle.data.vertices:v.co+=needle.location
  needle.location=pos((x,-.435,-.715));needle.parent=root
  for i in range(9):
   a=math.radians(-130+i*32.5);cube('dial_tick',(.005,.015,.006),(x+math.sin(a)*.081,-.435+math.cos(a)*.081,-.715),'instrument_light',root,.001)
 disc('limiter',.012,(wx+.27,-.435,-.715),'limiter',root)
 # Batch fixed pieces by material; named animation parts remain independent.
 animated={'bonnet','speed_needle','rpm_needle','limiter'}
 for parent in [root,wheel]:
  groups={}
  for o in list(parent.children):
   if o.type=='MESH' and o.name.split('.')[0] not in animated and not o.name.startswith('arm_'):groups.setdefault(o.data.materials[0].name,[]).append(o)
  for name,objects in groups.items():
   if len(objects)<2:continue
   bpy.ops.object.select_all(action='DESELECT')
   for o in objects:o.select_set(True)
   bpy.context.view_layer.objects.active=objects[0];bpy.ops.object.join();bpy.context.object.name=kind+'_'+name
 bpy.ops.object.select_all(action='DESELECT');root.select_set(True)
 for o in root.children_recursive:o.select_set(True)
 os.makedirs(ROOT+'/public/rally/v43',exist_ok=True)
 bpy.ops.export_scene.gltf(filepath=ROOT+'/public/rally/v43/'+kind+'-cockpit.glb',export_format='GLB',use_selection=True,use_active_scene=True,export_yup=True)
 tris=sum(len(o.data.polygons) for o in root.children_recursive if o.type=='MESH')
 return {'kind':kind,'polygons':tris,'bytes':os.path.getsize(ROOT+'/public/rally/v43/'+kind+'-cockpit.glb')}
summary=[make(False),make(True)]
bpy.ops.wm.save_as_mainfile(filepath=ROOT+'/art/rally/cockpits-v43.blend',copy=True)
bpy.context.window.scene=previous
result={'assets':summary,'source':ROOT+'/art/rally/cockpits-v43.blend'}
